-- EcoSafe public media bucket + admin-only mutation policies
INSERT INTO storage.buckets(id,name,public,file_size_limit,allowed_mime_types) VALUES('ecosafe-media','ecosafe-media',true,10485760,ARRAY['image/svg+xml','image/png','image/jpeg','image/webp']) ON CONFLICT(id) DO UPDATE SET public=true,file_size_limit=10485760,allowed_mime_types=EXCLUDED.allowed_mime_types;
DROP POLICY IF EXISTS ecosafe_media_public_read ON storage.objects; CREATE POLICY ecosafe_media_public_read ON storage.objects FOR SELECT TO public USING(bucket_id='ecosafe-media');
DROP POLICY IF EXISTS ecosafe_media_admin_insert ON storage.objects; CREATE POLICY ecosafe_media_admin_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='ecosafe-media' AND public.ecosafe_is_admin());
DROP POLICY IF EXISTS ecosafe_media_admin_update ON storage.objects; CREATE POLICY ecosafe_media_admin_update ON storage.objects FOR UPDATE TO authenticated USING(bucket_id='ecosafe-media' AND public.ecosafe_is_admin()) WITH CHECK(bucket_id='ecosafe-media' AND public.ecosafe_is_admin());
DROP POLICY IF EXISTS ecosafe_media_admin_delete ON storage.objects; CREATE POLICY ecosafe_media_admin_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='ecosafe-media' AND public.ecosafe_is_admin());
